#!/usr/bin/env python3
import sys

YES = "Yes"  # type: str
NO = "No"  # type: str

def is_kaibun(s):
    #print("checking:", s)
    rev_s = ''.join(list(reversed(s)))
    #print(s, rev_s)
    return s == rev_s

def solve(S: str):
    if not is_kaibun(S):
        print(NO)
        return
    N = len(S)
    if N % 2 == 0:
        print(NO)
        return
    if not is_kaibun(S[0:(N-1)//2]):
        print(NO)
        return
    if not is_kaibun(S[(N+3)//2-1:]):
        print(NO)
        return

    print(YES)
    return


# Generated by 1.1.6 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    S = next(tokens)  # type: str
    solve(S)

if __name__ == '__main__':
    main()
